// Carry locks of a retired entry over to the one it was merged into, unless
// that entry has its own lock for the field.
func (q *Queries) MoveFieldLocks(ctx context.Context, arg MoveFieldLocksParams) error {
	_, err := q.db.Exec(ctx, moveFieldLocks, arg.ToID, arg.FromID)
	return err
}

const repointRedirects = `-- name: RepointRedirects :exec
UPDATE entry_redirects SET to_id = $1 WHERE to_id = $2
`

type RepointRedirectsParams struct {
	ToID   uuid.UUID
	FromID uuid.UUID
}

// Keep redirect chains one hop long.
func (q *Queries) RepointRedirects(ctx context.Context, arg RepointRedirectsParams) error {
	_, err := q.db.Exec(ctx, repointRedirects, arg.ToID, arg.FromID)
	return err
}

const setEntryState = `-- name: SetEntryState :exec
UPDATE entries SET state = $1, merged_into = $2, updated_at = now() WHERE id = $3
`

